#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){string s;getline(cin,s);
vector<int>st;st.push_back(-1);int best=0;
for(int i=0;i<(int)s.size();++i){
if(s[i]=='(')st.push_back(i);
else{st.pop_back();
if(st.empty())st.push_back(i);
else best=max(best,i-st.back());}}
printf("%d\n",best);return 0;}

